//! The schema: an ordered collection of [`SettingSpec`]s plus aliases.
//!
//! Schemas are built by [`Schema::baseline`] from the table generated by
//! `build.rs`, or programmatically with [`Schema::insert`]. The station crate
//! merges its own settings into a baseline schema with [`Schema::merge`].

use std::collections::BTreeMap;

use crate::dimension::Dimension;
use crate::error::{ConfigError, ConfigResult, SchemaError};
use crate::ids::SettingId;
use crate::spec::{Kind, SettingSpec};
use crate::util;

/// One row of the generated setting table.
///
/// The columns are key, kind specification, default, required flag, aliases,
/// deprecation hint and documentation.
pub type SettingSeed = (
    &'static str,
    &'static str,
    Option<&'static str>,
    bool,
    &'static [&'static str],
    Option<&'static str>,
    &'static str,
);

/// What [`Schema::merge`] does when a key already exists.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
pub enum MergePolicy {
    /// Fail with [`SchemaError::MergeConflict`].
    #[default]
    Reject,
    /// Replace the existing specification, keeping its identifier.
    Override,
    /// Keep the existing specification and skip the new one.
    KeepExisting,
}

/// An ordered set of setting specifications.
#[derive(Debug, Clone, Default)]
pub struct Schema {
    specs: BTreeMap<String, SettingSpec>,
    aliases: BTreeMap<String, String>,
    groups: BTreeMap<String, Vec<String>>,
    next_id: u32,
}

impl Schema {
    /// An empty schema.
    pub fn new() -> Self {
        Self::default()
    }

    /// The schema generated from `data/settings.txt`.
    ///
    /// # Panics
    ///
    /// Panics only when the generated table is inconsistent, which `build.rs`
    /// already rules out at compile time.
    pub fn baseline() -> Self {
        let schema = Self::from_seed(crate::generated::SETTING_SEED)
            .expect("the generated baseline schema is validated by build.rs");
        debug_assert_eq!(
            schema.len(),
            crate::generated::GENERATED_SETTING_COUNT,
            "the generated setting table changed size"
        );
        schema
    }

    /// Builds a schema from generated seed rows.
    ///
    /// # Errors
    ///
    /// Returns [`SchemaError`] for malformed kinds, defaults or keys and for
    /// duplicate keys and aliases.
    pub fn from_seed(seed: &[SettingSeed]) -> Result<Self, SchemaError> {
        let mut schema = Self::new();
        for (key, kind, default, required, aliases, deprecated, doc) in seed {
            let kind = Kind::from_spec(kind)?;
            let mut builder = SettingSpec::builder(*key, kind).doc(*doc);
            if *required {
                builder = builder.required();
            }
            if let Some(text) = default {
                builder = builder.default_text(text)?;
            }
            for alias in *aliases {
                builder = builder.alias(*alias);
            }
            if let Some(hint) = deprecated {
                builder = builder.deprecated(*hint);
            }
            schema.insert(builder.build()?)?;
        }
        Ok(schema)
    }

    /// Adds a specification, assigning it an identifier and registering its
    /// aliases.
    ///
    /// # Errors
    ///
    /// Returns [`SchemaError::DuplicateKey`] or [`SchemaError::AliasConflict`]
    /// when the key or one of its aliases is already known.
    pub fn insert(&mut self, mut spec: SettingSpec) -> Result<SettingId, SchemaError> {
        let key = spec.key().to_string();
        if self.specs.contains_key(&key) {
            return Err(SchemaError::DuplicateKey { key });
        }
        let aliases: Vec<String> = spec.aliases().to_vec();
        for alias in &aliases {
            if self.specs.contains_key(alias) {
                return Err(SchemaError::AliasConflict {
                    alias: alias.clone(),
                    owner: key,
                });
            }
            if let Some(owner) = self.aliases.get(alias) {
                return Err(SchemaError::AliasConflict {
                    alias: alias.clone(),
                    owner: owner.clone(),
                });
            }
        }
        let id = SettingId::new(self.next_id);
        self.next_id += 1;
        spec.assign_id(id);
        self.specs.insert(key.clone(), spec);
        for alias in aliases {
            self.aliases.insert(alias, key.clone());
        }
        Ok(id)
    }

    /// Looks a key up, falling back to aliases.
    pub fn get(&self, key: &str) -> Option<&SettingSpec> {
        self.resolve(key)
    }

    /// Looks a key or alias up.
    pub fn resolve(&self, key: &str) -> Option<&SettingSpec> {
        let needle = key.trim();
        if let Some(spec) = self.specs.get(needle) {
            return Some(spec);
        }
        self.aliases
            .get(needle)
            .and_then(|canonical| self.specs.get(canonical))
    }

    /// Looks a key or alias up, reporting [`ConfigError::UnknownKey`] with a
    /// suggestion when nothing matches.
    ///
    /// # Errors
    ///
    /// Returns [`ConfigError::UnknownKey`] for unknown keys.
    pub fn require(&self, key: &str) -> ConfigResult<&SettingSpec> {
        self.resolve(key).ok_or_else(|| ConfigError::UnknownKey {
            key: key.trim().to_string(),
            suggestion: self.suggest(key),
        })
    }

    /// The closest known key or alias, if one is close enough.
    pub fn suggest(&self, key: &str) -> Option<String> {
        let needle = key.trim();
        let canonical = self
            .specs
            .keys()
            .map(String::as_str)
            .chain(self.aliases.keys().map(String::as_str));
        util::closest(needle, canonical, 4).map(str::to_string)
    }

    /// Looks a specification up by identifier.
    pub fn by_id(&self, id: SettingId) -> Option<&SettingSpec> {
        self.specs.values().find(|spec| spec.id() == id)
    }

    /// Iterates over every specification in key order.
    pub fn iter(&self) -> impl Iterator<Item = &SettingSpec> {
        self.specs.values()
    }

    /// Every key in key order.
    pub fn keys(&self) -> impl Iterator<Item = &str> {
        self.specs.keys().map(String::as_str)
    }

    /// Every alias with the key that owns it.
    pub fn aliases(&self) -> impl Iterator<Item = (&str, &str)> {
        self.aliases
            .iter()
            .map(|(alias, key)| (alias.as_str(), key.as_str()))
    }

    /// Number of specifications.
    pub fn len(&self) -> usize {
        self.specs.len()
    }

    /// Whether the schema is empty.
    pub fn is_empty(&self) -> bool {
        self.specs.is_empty()
    }

    /// The specifications that must have a value.
    pub fn required_specs(&self) -> Vec<&SettingSpec> {
        self.specs.values().filter(|spec| spec.required()).collect()
    }

    /// The specifications whose key starts with `prefix`.
    pub fn keys_matching(&self, prefix: &str) -> Vec<&SettingSpec> {
        self.specs
            .values()
            .filter(|spec| spec.key().starts_with(prefix))
            .collect()
    }

    /// Groups specifications by dimension, which is how `units` reports them.
    pub fn by_dimension(&self) -> BTreeMap<Dimension, Vec<String>> {
        let mut grouped: BTreeMap<Dimension, Vec<String>> = BTreeMap::new();
        for spec in self.specs.values() {
            if let Some(dimension) = spec.kind().dimension() {
                grouped
                    .entry(dimension)
                    .or_default()
                    .push(spec.key().to_string());
            }
        }
        grouped
    }

    /// Merges another schema into this one.
    ///
    /// # Errors
    ///
    /// With [`MergePolicy::Reject`] a colliding key returns
    /// [`SchemaError::MergeConflict`]; alias conflicts of new keys are always
    /// reported.
    pub fn merge(&mut self, other: &Schema, policy: MergePolicy) -> Result<usize, SchemaError> {
        let mut merged = 0;
        for spec in other.iter() {
            let key = spec.key().to_string();
            match self.specs.get(&key) {
                None => {
                    self.insert(spec.clone())?;
                    merged += 1;
                }
                Some(existing) => match policy {
                    MergePolicy::Reject => return Err(SchemaError::MergeConflict { key }),
                    MergePolicy::KeepExisting => {}
                    MergePolicy::Override => {
                        let id = existing.id();
                        self.aliases.retain(|_, owner| owner != &key);
                        let mut replacement = spec.clone();
                        replacement.assign_id(id);
                        for alias in replacement.aliases() {
                            if let Some(owner) = self.aliases.get(alias)
                                && owner != &key
                            {
                                return Err(SchemaError::AliasConflict {
                                    alias: alias.clone(),
                                    owner: owner.clone(),
                                });
                            }
                        }
                        let aliases: Vec<String> = replacement.aliases().to_vec();
                        self.specs.insert(key.clone(), replacement);
                        for alias in aliases {
                            self.aliases.insert(alias, key.clone());
                        }
                        merged += 1;
                    }
                },
            }
        }
        Ok(merged)
    }

    /// Names a group of keys, so `list` can report them together.
    ///
    /// # Errors
    ///
    /// Returns [`SchemaError::UnknownKey`] when a key is not in the schema.
    pub fn add_group(&mut self, name: &str, keys: &[&str]) -> Result<SettingId, SchemaError> {
        let mut canonical = Vec::new();
        for key in keys {
            let spec = self.resolve(key).ok_or_else(|| SchemaError::UnknownKey {
                key: (*key).to_string(),
            })?;
            canonical.push(spec.key().to_string());
        }
        self.groups.insert(name.to_string(), canonical);
        Ok(SettingId::new(
            u32::try_from(self.groups.len().saturating_sub(1)).unwrap_or(0),
        ))
    }

    /// The keys of a named group.
    pub fn group(&self, name: &str) -> Option<&[String]> {
        self.groups.get(name).map(Vec::as_slice)
    }

    /// Every group name in order.
    pub fn group_names(&self) -> impl Iterator<Item = &str> {
        self.groups.keys().map(String::as_str)
    }
}

#[cfg(test)]
mod tests {
    use super::{MergePolicy, Schema};
    use crate::dimension::Dimension;
    use crate::error::{ConfigError, SchemaError};
    use crate::generated::{GENERATED_SETTING_COUNT, SETTING_SEED};
    use crate::spec::{Kind, SettingSpec};
    use crate::value::SettingValue;

    #[test]
    fn the_generated_schema_matches_its_table() {
        let schema = Schema::baseline();
        assert_eq!(schema.len(), GENERATED_SETTING_COUNT);
        assert!(schema.len() >= 20);
        assert!(!schema.is_empty());
        assert_eq!(schema.keys().count(), GENERATED_SETTING_COUNT);
        assert_eq!(schema.iter().count(), GENERATED_SETTING_COUNT);
        assert_eq!(schema.keys().next(), Some("fluid.density"));
        assert_eq!(SETTING_SEED.len(), GENERATED_SETTING_COUNT);
        assert!(crate::validation::RuleSet::baseline().len() >= 5);
    }

    #[test]
    fn identifiers_are_assigned_in_key_order() {
        let schema = Schema::baseline();
        let ids: Vec<u32> = schema.iter().map(|spec| spec.id().get()).collect();
        assert_eq!(ids.first().copied(), Some(0));
        for (index, id) in ids.iter().enumerate() {
            assert_eq!(*id, u32::try_from(index).unwrap());
        }
        let first = schema.iter().next().expect("schema is not empty");
        assert_eq!(
            schema.by_id(first.id()).map(SettingSpec::key),
            Some(first.key())
        );
        assert_eq!(schema.by_id(crate::ids::SettingId::new(500)), None);
    }

    #[test]
    fn aliases_resolve_to_their_key() {
        let schema = Schema::baseline();
        let by_alias = schema.resolve("kp").expect("kp is an alias");
        assert_eq!(by_alias.key(), "loop.gain");
        assert_eq!(schema.resolve("gain"), None);
        assert_eq!(
            schema.require("nothing.here").unwrap_err(),
            ConfigError::UnknownKey {
                key: "nothing.here".to_string(),
                suggestion: None,
            }
        );
        assert_eq!(schema.resolve("loop.gian").map(SettingSpec::key), None);
        assert_eq!(
            schema.require("loop.gian").unwrap_err(),
            ConfigError::UnknownKey {
                key: "loop.gian".to_string(),
                suggestion: Some("loop.gain".to_string()),
            }
        );
        assert_eq!(schema.aliases().count(), 14);
        assert_eq!(
            schema.get("supply.temp").map(SettingSpec::key),
            Some("sensor.supply.temperature")
        );
    }

    #[test]
    fn defaults_are_typed_at_build_time() {
        let schema = Schema::baseline();
        let interval = schema.require("sample.interval").expect("present");
        let default = interval.default().expect("has a default");
        let quantity = default.as_quantity().expect("quantity default");
        assert_eq!(quantity.canonical(), 1.0);
        let speed = schema.require("motor.nominal.speed").expect("present");
        let quantity = speed
            .default()
            .expect("has a default")
            .as_quantity()
            .expect("quantity");
        assert!((quantity.canonical() - 24.166_666_666_666_666).abs() < 1e-9);
        assert_eq!(schema.required_specs().len(), 3);
    }

    #[test]
    fn inserts_detect_collisions() {
        let mut schema = Schema::baseline();
        let duplicate = SettingSpec::builder("loop.gain", Kind::bool())
            .build()
            .expect("valid");
        assert_eq!(
            schema.insert(duplicate),
            Err(SchemaError::DuplicateKey {
                key: "loop.gain".to_string()
            })
        );
        let alias_collision = SettingSpec::builder("loop.extra", Kind::bool())
            .alias("kp")
            .build()
            .expect("valid");
        assert_eq!(
            schema.insert(alias_collision),
            Err(SchemaError::AliasConflict {
                alias: "kp".to_string(),
                owner: "loop.gain".to_string()
            })
        );
        let key_collision = SettingSpec::builder("loop.extra", Kind::bool())
            .alias("loop.gain")
            .build()
            .expect("valid");
        assert_eq!(
            schema.insert(key_collision),
            Err(SchemaError::AliasConflict {
                alias: "loop.gain".to_string(),
                owner: "loop.extra".to_string()
            })
        );
        let fresh = SettingSpec::builder("loop.extra", Kind::bool())
            .doc("extra flag")
            .build()
            .expect("valid");
        let id = schema.insert(fresh).expect("insert succeeds");
        assert_eq!(schema.len(), GENERATED_SETTING_COUNT + 1);
        assert_eq!(schema.by_id(id).map(SettingSpec::key), Some("loop.extra"));
    }

    #[test]
    fn merging_follows_the_policy() {
        let mut base = Schema::baseline();
        let mut overlay = Schema::new();
        overlay
            .insert(
                SettingSpec::builder("station.mode", Kind::text(16))
                    .default_text("auto")
                    .expect("default parses")
                    .doc("operating mode")
                    .build()
                    .expect("valid"),
            )
            .expect("insert succeeds");
        overlay
            .insert(
                SettingSpec::builder("loop.gain", Kind::float(0.0, 10.0))
                    .default_value(SettingValue::Float(2.0))
                    .build()
                    .expect("valid"),
            )
            .expect("insert succeeds");

        let mut rejecting = base.clone();
        assert_eq!(
            rejecting.merge(&overlay, MergePolicy::Reject),
            Err(SchemaError::MergeConflict {
                key: "loop.gain".to_string()
            })
        );

        let mut keeping = base.clone();
        assert_eq!(
            keeping.merge(&overlay, MergePolicy::KeepExisting).unwrap(),
            1
        );
        assert_eq!(keeping.len(), GENERATED_SETTING_COUNT + 1);
        assert_eq!(
            keeping.require("loop.gain").unwrap().kind(),
            &Kind::float(0.0, 1000.0)
        );

        let merging = base.merge(&overlay, MergePolicy::Override).unwrap();
        assert_eq!(merging, 2);
        assert_eq!(base.len(), GENERATED_SETTING_COUNT + 1);
        assert_eq!(
            base.require("loop.gain").unwrap().kind(),
            &Kind::float(0.0, 10.0)
        );
        assert_eq!(
            base.require("loop.gain").unwrap().id(),
            crate::ids::SettingId::new(11)
        );
    }

    #[test]
    fn groups_and_dimensions_are_reported() {
        let mut schema = Schema::baseline();
        let id = schema
            .add_group("readout", &["sensor.supply.temperature", "return.temp"])
            .expect("group is valid");
        assert_eq!(id.get(), 0);
        assert_eq!(
            schema.group("readout"),
            Some(
                [
                    "sensor.supply.temperature".to_string(),
                    "sensor.return.temperature".to_string()
                ]
                .as_slice()
            )
        );
        assert_eq!(
            schema.add_group("broken", &["does.not.exist"]),
            Err(SchemaError::UnknownKey {
                key: "does.not.exist".to_string()
            })
        );
        assert_eq!(schema.group_names().collect::<Vec<&str>>(), vec!["readout"]);
        assert_eq!(schema.group("missing"), None);

        let grouped = schema.by_dimension();
        assert!(grouped.contains_key(&Dimension::TEMPERATURE));
        assert_eq!(grouped[&Dimension::TEMPERATURE].len(), 2);
        assert_eq!(grouped[&Dimension::PRESSURE].len(), 3);
        assert!(!grouped.contains_key(&Dimension::CURRENT));
    }

    #[test]
    fn key_filters_and_prefixes() {
        let schema = Schema::baseline();
        let loop_keys: Vec<&str> = schema
            .keys_matching("loop.")
            .into_iter()
            .map(SettingSpec::key)
            .collect();
        assert_eq!(
            loop_keys,
            vec!["loop.enabled", "loop.gain", "loop.integral", "loop.name"]
        );
        assert_eq!(schema.keys_matching("nothing.").len(), 0);
    }

    #[test]
    fn empty_schemas_are_legal() {
        let schema = Schema::new();
        assert!(schema.is_empty());
        assert_eq!(schema.len(), 0);
        assert_eq!(schema.suggest("anything"), None);
        assert!(schema.required_specs().is_empty());
    }
}
